import {FrameAccurateScrubberBody,type FrameAccurateScrubberProps} from '@/components/nyc-tron/ui/components/forge/timeline/FrameAccurateScrubber.shared';
export type {FrameAccurateScrubberProps,FrameSeekRequest,FrameSeekResult} from '@/components/nyc-tron/ui/components/forge/timeline/FrameAccurateScrubber.shared';
